WITH f AS (SELECT 'activities_deal_id_fkey' AS fk,count(*) AS errors FROM public."activities" r WHERE r."deal_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."deal_id") UNION ALL SELECT 'activities_organization_id_fkey' AS fk,count(*) AS errors FROM public."activities" r WHERE r."organization_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."organizations" p WHERE p."id"=r."organization_id") UNION ALL SELECT 'advisory_deals_site_id_fkey' AS fk,count(*) AS errors FROM public."advisory_deals" r WHERE r."site_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."sites" p WHERE p."site_id"=r."site_id") UNION ALL SELECT 'assignment_history_inquiry_id_fkey' AS fk,count(*) AS errors FROM public."assignment_history" r WHERE r."inquiry_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."inquiries" p WHERE p."id"=r."inquiry_id") UNION ALL SELECT 'assignment_history_opportunity_id_fkey' AS fk,count(*) AS errors FROM public."assignment_history" r WHERE r."opportunity_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."opportunity_id") UNION ALL SELECT 'audit_logs_actor_id_fkey' AS fk,count(*) AS errors FROM public."audit_logs" r WHERE r."actor_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."users" p WHERE p."user_id"=r."actor_id") UNION ALL SELECT 'business_history_deal_id_fkey' AS fk,count(*) AS errors FROM public."business_history" r WHERE r."deal_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."deal_id") UNION ALL SELECT 'contact_assignments_person_key_fkey' AS fk,count(*) AS errors FROM public."contact_assignments" r WHERE r."person_key" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."contacts" p WHERE p."person_key"=r."person_key") UNION ALL SELECT 'contacts_organization_id_fkey' AS fk,count(*) AS errors FROM public."contacts" r WHERE r."organization_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."organizations" p WHERE p."id"=r."organization_id") UNION ALL SELECT 'deals_contact_id_fkey' AS fk,count(*) AS errors FROM public."deals" r WHERE r."contact_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."contacts" p WHERE p."id"=r."contact_id") UNION ALL SELECT 'deals_organization_id_fkey' AS fk,count(*) AS errors FROM public."deals" r WHERE r."organization_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."organizations" p WHERE p."id"=r."organization_id") UNION ALL SELECT 'deals_origin_inquiry_id_fkey' AS fk,count(*) AS errors FROM public."deals" r WHERE r."origin_inquiry_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."inquiries" p WHERE p."id"=r."origin_inquiry_id") UNION ALL SELECT 'deals_owner_id_fkey' AS fk,count(*) AS errors FROM public."deals" r WHERE r."owner_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."users" p WHERE p."user_id"=r."owner_id") UNION ALL SELECT 'deals_site_id_fkey' AS fk,count(*) AS errors FROM public."deals" r WHERE r."site_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."sites" p WHERE p."site_id"=r."site_id") UNION ALL SELECT 'inquiries_assigned_to_fkey' AS fk,count(*) AS errors FROM public."inquiries" r WHERE r."assigned_to" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."users" p WHERE p."user_id"=r."assigned_to") UNION ALL SELECT 'inquiries_deal_id_fkey' AS fk,count(*) AS errors FROM public."inquiries" r WHERE r."deal_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."deal_id") UNION ALL SELECT 'inquiries_opportunity_id_fkey' AS fk,count(*) AS errors FROM public."inquiries" r WHERE r."opportunity_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."opportunity_id") UNION ALL SELECT 'inquiries_site_id_fkey' AS fk,count(*) AS errors FROM public."inquiries" r WHERE r."site_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."sites" p WHERE p."site_id"=r."site_id") UNION ALL SELECT 'next_actions_deal_id_fkey' AS fk,count(*) AS errors FROM public."next_actions" r WHERE r."deal_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."deal_id") UNION ALL SELECT 'next_actions_inquiry_id_fkey' AS fk,count(*) AS errors FROM public."next_actions" r WHERE r."inquiry_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."inquiries" p WHERE p."id"=r."inquiry_id") UNION ALL SELECT 'next_actions_source_activity_id_fkey' AS fk,count(*) AS errors FROM public."next_actions" r WHERE r."source_activity_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."activities" p WHERE p."id"=r."source_activity_id") UNION ALL SELECT 'notes_deal_id_fkey' AS fk,count(*) AS errors FROM public."notes" r WHERE r."deal_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."deal_id") UNION ALL SELECT 'notes_organization_id_fkey' AS fk,count(*) AS errors FROM public."notes" r WHERE r."organization_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."organizations" p WHERE p."id"=r."organization_id") UNION ALL SELECT 'projects_opportunity_id_fkey' AS fk,count(*) AS errors FROM public."projects" r WHERE r."opportunity_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."opportunity_id") UNION ALL SELECT 'projects_site_id_fkey' AS fk,count(*) AS errors FROM public."projects" r WHERE r."site_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."sites" p WHERE p."site_id"=r."site_id") UNION ALL SELECT 'stage_history_actor_id_fkey' AS fk,count(*) AS errors FROM public."stage_history" r WHERE r."actor_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."users" p WHERE p."user_id"=r."actor_id") UNION ALL SELECT 'stage_history_inquiry_id_fkey' AS fk,count(*) AS errors FROM public."stage_history" r WHERE r."inquiry_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."inquiries" p WHERE p."id"=r."inquiry_id") UNION ALL SELECT 'stage_history_opportunity_id_fkey' AS fk,count(*) AS errors FROM public."stage_history" r WHERE r."opportunity_id" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."deals" p WHERE p."id"=r."opportunity_id")) SELECT jsonb_build_object('fk_count',(SELECT count(*) FROM f),'fk_errors',(SELECT sum(errors) FROM f),'unvalidated_constraints',(SELECT count(*) FROM pg_constraint WHERE connamespace='public'::regnamespace AND NOT convalidated)) AS fk_verification;
